def json_str(text):
    parts = []
    for char in text:
        cp = ord(char)
        if cp == 34:
            parts.append('\\"')
        elif cp == 92:
            parts.append("\\\\")
        elif cp == 10:
            parts.append("\\n")
        elif cp == 13:
            parts.append("\\r")
        elif cp == 9:
            parts.append("\\t")
        elif cp < 32 or cp == 127:
            parts.append(f"\\u{cp:04x}")
        else:
            parts.append(char)
    return '"' + "".join(parts) + '"'


def flat(values):
    return "|".join(json_str(item) for item in values)


