    with warnings.catch_warnings():
        warnings.simplefilter("ignore")
        cities1 = ASCIIfy(["S\u00e3o Paulo", "Reykjav\u00edk"], 1)
        cities2 = ASCIIfy(["S\u00e3o Paulo", "Reykjav\u00edk"], 2)
        athens = ASCIIfy("\u0391\u03b8\u03ae\u03bd\u03b1")
        bulk1 = ASCIIfy(
