    for char in text:
        cp = ord(char)
        if cp == 34:
            parts.append('\\"')
        elif cp == 92:
            parts.append("\\\\")
        elif cp == 10:
            parts.append("\\n")
        elif cp == 13:
            parts.append("\\r")
        elif cp == 9:
