def fmt(v):
    if v is NA:
        return "NA"
    if isinstance(v, complex) or (isinstance(v, np.complexfloating)):
        re = float(np.real(v))
        im = float(np.imag(v))
        if np.isnan(re) or np.isnan(im):
            return "NA"
        return f"{re:.16g}+{im:.16g}i"
    if isinstance(v, (bool, np.bool_)):
        return "TRUE" if v else "FALSE"
    if isinstance(v, str):
        return json_str(v)
