        if np.int32(v) == _NA_INT:
            return "NA"
        return format(float(v), ".16g")
    if isinstance(v, (np.floating, float)):
        if np.isnan(v):
            return "NA"
        return format(float(v), ".16g")
    if isinstance(v, np.int8):
